import { describe, it, expect, vi } from 'vitest'
import { NextRequest, NextResponse } from 'next/server'
import { middleware as namedMiddleware, default as defaultMiddleware } from './middleware'

describe('Next.js Middleware', () => {
  it('exports middleware as both named and default', () => {
    expect(typeof namedMiddleware).toBe('function')
    expect(typeof defaultMiddleware).toBe('function')
    expect(namedMiddleware).toBe(defaultMiddleware)
  })

  it('adds custom header X-Request-Id with unique values to responses', () => {
    const req1 = new NextRequest('http://localhost:3000/test-one')
    const res1 = namedMiddleware(req1)

    const req2 = new NextRequest('http://localhost:3000/test-two')
    const res2 = namedMiddleware(req2)

    const id1 = res1.headers.get('x-request-id')
    const id2 = res2.headers.get('x-request-id')

    expect(id1).toBeTruthy()
    expect(id2).toBeTruthy()
    expect(id1).not.toBe(id2)

    // Check UUID format
    expect(id1).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i)
  })

  it('logs the request pathname to the console', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {})

    const req = new NextRequest('http://localhost:3000/api/users')
    namedMiddleware(req)

    expect(consoleSpy).toHaveBeenCalledWith('/api/users')

    consoleSpy.mockRestore()
  })

  it('handles root pathname correctly', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {})

    const req = new NextRequest('http://localhost:3000/')
    namedMiddleware(req)

    expect(consoleSpy).toHaveBeenCalledWith('/')

    consoleSpy.mockRestore()
  })
})

